const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=value=>Number.isFinite(Date.parse(value))?new Date(value).toISOString().replace('T',' ').slice(0,16)+' UTC':'Not yet retrieved';
const safePost=value=>/^https:\/\/x\.com\/HormuzLetter\/status\/\d+$/.test(value||'')?value:null;

export function renderSourceWatch(state,now=Date.now()){
 const data=state.sourceWatch,source=data?.source,items=(data?.items||[]).filter(item=>safePost(item.url));
 const failed=state.failures?.sourceWatch||['cached','unavailable'].includes(source?.connection);
 const overdue=Number.isFinite(Date.parse(source?.retrievedAt))&&now-Date.parse(source.retrievedAt)>=(source.freshnessAfterSeconds??900)*1000;
 const status=failed?(items.length?'Update failed · retained excerpts':'Source excerpt unavailable'):source?.status==='stale'||overdue?'Tracked-post check overdue':data?'Tracked posts checked':'Checking tracked posts…';
 return `<div class="source-watch-heading"><div><span class="eyebrow">PREFERRED SOURCE</span><h2>The Hormuz Letter</h2></div><a href="https://x.com/HormuzLetter" target="_blank" rel="noopener noreferrer">Latest posts on X ↗</a></div>
 <p class="source-watch-scope">Tracked links only · new-post discovery is not connected.</p><p class="source-watch-status">${esc(status)} · retrieved ${esc(stamp(source?.retrievedAt))}${state.auto===false?' · view refresh paused':''}</p>
 <div class="source-watch-items">${items.length?items.map(item=>`<article><div class="source-watch-meta">Reported by The Hormuz Letter · ${esc(item.publishedAt?.slice(0,10)||'Publication date unavailable')}</div><p>${esc(item.summary||item.title)}</p><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Read full post &amp; maps ↗</a></article>`).join(''):`<p class="source-watch-empty">${failed?'The excerpt could not be retrieved. Open the source directly for its latest reporting.':'Retrieving public excerpts of posts added to this watch.'}</p>`}</div>
 <details data-source-watch-details><summary>What this watch includes</summary><p>Only explicitly tracked posts are checked every five minutes. New posts are not discovered automatically. Excerpts may be shortened by X; the original post contains the full report and media.</p><p>Attribution and uncertainty remain with the source. A reported attack does not establish the amount of oil production lost.</p><div class="source-watch-tools"><a href="https://firms.modaps.eosdis.nasa.gov/map/" target="_blank" rel="noopener noreferrer">NASA FIRMS · heat detections ↗</a><a href="https://browser.dataspace.copernicus.eu/" target="_blank" rel="noopener noreferrer">Copernicus · satellite imagery ↗</a></div><p>These satellite tools open at the provider; their observations are not yet collected by Passage.</p></details>`;
}
export function createSourceWatchView(host,{getState}){
 return {update(){const markup=renderSourceWatch(getState());if(host.dataset.markup===markup)return;const expanded=host.querySelector('details')?.open;const active=host.ownerDocument.activeElement;const href=host.contains(active)?active.getAttribute('href'):null;const summaryFocused=host.contains(active)&&active.tagName==='SUMMARY';host.innerHTML=markup;host.dataset.markup=markup;if(expanded)host.querySelector('details').open=true;if(summaryFocused)host.querySelector('summary').focus({preventScroll:true});else if(href)[...host.querySelectorAll('a')].find(a=>a.getAttribute('href')===href)?.focus({preventScroll:true});}};
}
